/**
 * get_pagination_guide tool — cursor-based pagination pattern for a query.
 */
import { z } from 'zod';
export const getPaginationGuideSchema = z.object({
    query_name: z.string().max(200).optional().describe('Name of a list query (e.g. "transactions", "tokens"). Defaults to "transactions" if omitted.'),
});
export function handleGetPaginationGuide(input, schema) {
    const listQueries = schema
        ? schema.rootQueries.filter(q => q.isList).map(q => q.name)
        : [];
    let queryName = (input.query_name ?? 'transactions').toLowerCase().trim();
    let note = '';
    if (listQueries.length > 0 && !listQueries.includes(queryName)) {
        note = `\n\n> **Note:** \`${queryName}\` is not a recognized list query. Showing pattern for \`transactions\` instead. Valid list queries: ${listQueries.join(', ')}.\n`;
        queryName = 'transactions';
    }
    return `# Pagination Guide${input.query_name ? ` — \`${queryName}\`` : ''}${note}

OneSource uses **cursor-based pagination** (NOT offset-based). All list queries follow the same pattern.

## Response Shape

\`\`\`graphql
query {
  ${queryName}(first: 10) {
    entries {
      # ... fields for each item
    }
    pageInfo {
      hasNextPage
      endCursor
      count
    }
    totalCount
  }
}
\`\`\`

**Key fields:**
- \`entries[]\` — Array of result items (NOT \`edges\`/\`node\`)
- \`pageInfo.hasNextPage\` — \`true\` if more results exist
- \`pageInfo.endCursor\` — Opaque cursor string to pass as \`after\` for the next page
- \`pageInfo.count\` — Number of items in *this* page
- \`totalCount\` — Total items matching the query/filter

## Step-by-Step Flow

1. **First page:** Send \`first: N\` (default 10, max varies by query)
2. **Check:** Read \`pageInfo.hasNextPage\`
3. **Next page:** If \`true\`, send \`first: N, after: "<endCursor>"\`
4. **Repeat** until \`hasNextPage\` is \`false\`

**Example — page through \`${queryName}\`:**

\`\`\`graphql
# Page 1
query {
  ${queryName}(first: 25) {
    entries { ... }
    pageInfo { hasNextPage endCursor }
  }
}

# Page 2 (use endCursor from page 1)
query {
  ${queryName}(first: 25, after: "eyJsYXN0X2lkIjoiMTIzIn0=") {
    entries { ... }
    pageInfo { hasNextPage endCursor }
  }
}
\`\`\`

## Common Mistakes

| Mistake | Fix |
|---------|-----|
| Using \`edges\`/\`node\` (Relay style) | Use \`entries[]\` directly — OneSource does NOT use Relay connection spec |
| Using \`offset\`/\`skip\` | Use \`after\` with the cursor string from \`pageInfo.endCursor\` |
| Forgetting \`first\` | Always pass \`first\` to control page size |
| Treating \`endCursor\` as a number | It's an opaque string — pass it exactly as received |${listQueries.length > 0 ? `\n\n**List queries supporting pagination:** ${listQueries.join(', ')}` : ''}`;
}
